class Solution {
public:
    int maxSizedArray(long long s) {
        const int MX = 1330;
        static vector<long long> f(MX, 0);
        static bool initialized = false;
        if (!initialized) {
            initialized = true;
            for (int i = 1; i < MX; ++i) {
                f[i] = f[i - 1] + i;
                for (int j = 0; j < i; ++j) {
                    f[i] += 2 * (i | j);
                }
            }
        }

        int l = 1, r = MX;
        while (l < r) {
            int m = (l + r + 1) / 2;
            long long cost = f[m - 1] * (m - 1) * m / 2;
            if (cost <= s) {
                l = m;
            } else {
                r = m - 1;
            }
        }
        return l;
    }
};

class Solution {
    private static final int MX = 1330;
    private static final long[] f = new long[MX];
    static {
        for (int i = 1; i < MX; ++i) {
            f[i] = f[i - 1] + i;
            for (int j = 0; j < i; ++j) {
                f[i] += 2 * (i | j);
            }
        }
    }

    public int maxSizedArray(long s) {
        int l = 1, r = MX;
        while (l < r) {
            int m = (l + r + 1) / 2;
            long cost = f[m - 1] * (m - 1) * m / 2;
            if (cost <= s) {
                l = m;
            } else {
                r = m - 1;
            }
        }
        return l;
    }
}

var maxSizedArray = function(s) {
    const MX = 1330;
    const f = new Array(MX).fill(0n);
    for (let i = 1; i < MX; i++) {
        f[i] = f[i - 1] + BigInt(i);
        for (let j = 0; j < i; j++) {
            f[i] += 2n * BigInt(i | j);
        }
    }

    const target = BigInt(s);
    let l = 1, r = MX;
    while (l < r) {
        const m = Math.floor((l + r + 1) / 2);
        const cost = f[m - 1] * BigInt(m - 1) * BigInt(m) / 2n;
        if (cost <= target) {
            l = m;
        } else {
            r = m - 1;
        }
    }
    return l;
};
